from src.nodes.base import BaseNode
from src.runtime.assets.semantic import (
    get_asset_environment_mapper, get_asset_query_engine,
    BUILTIN_ENVIRONMENTS,
)

class Hou_Mcp_Asset_Environment(BaseNode):
    name = "hou_mcp_asset_environment"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",      "string", widget_type="text", default="map")
        self.add_input("asset_data",  "any")
        self.add_input("environment", "string", widget_type="text")
        self.add_input("limit",       "int",    widget_type="int", default=20)
        self.add_output("environments", "list")
        self.add_output("primary_env",  "string")
        self.add_output("assets",       "list")
        self.add_output("result",       "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action      = str(inputs.get("action") or "map").strip().lower()
        asset_data  = inputs.get("asset_data") or {}
        environment = str(inputs.get("environment") or "").strip()
        limit       = int(inputs.get("limit") or 20)
        try:
            if action == "map":
                mapping = get_asset_environment_mapper().map_environments(
                    asset_data if isinstance(asset_data, dict) else {}
                )
                return {
                    "environments": mapping.environments,
                    "primary_env":  mapping.primary,
                    "assets":       [],
                    "result":       mapping.to_dict(),
                    "exec_out":     True,
                }
            elif action == "rank":
                ranked = get_asset_environment_mapper().rank_environment_fit(
                    asset_data if isinstance(asset_data, dict) else {}
                )
                return {
                    "environments": [r["environment"] for r in ranked],
                    "primary_env":  ranked[0]["environment"] if ranked else "",
                    "assets":       [],
                    "result":       ranked,
                    "exec_out":     True,
                }
            elif action == "query":
                result = get_asset_query_engine().query_environment(environment, limit=limit)
                return {
                    "environments": [environment],
                    "primary_env":  environment,
                    "assets":       result.assets,
                    "result":       result.to_dict(),
                    "exec_out":     True,
                }
            elif action == "list_environments":
                return {
                    "environments": sorted(BUILTIN_ENVIRONMENTS),
                    "primary_env":  "",
                    "assets":       [],
                    "result":       {"environments": sorted(BUILTIN_ENVIRONMENTS)},
                    "exec_out":     True,
                }
            else:
                return {"environments": [], "primary_env": "", "assets": [], "result": {}, "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_environment failed: {e}")
            return {"environments": [], "primary_env": "", "assets": [], "result": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Environment
